type Props = {
  tasks: Task[];
  selectedId: number;
  onSelect: (id: number) => void;
  onEdit: (id: number) => void;
};

export function TaskList({ tasks, selectedId, onSelect, onEdit }: Props) {
  const [query, setQuery] = useState('');
  const [showClear, setShowClear] = useState(false);

  const normalizedQuery = query.trim().toLowerCase();
  const visibleTasks = normalizedQuery
    ? tasks.filter((task) => task.title.toLowerCase().includes(normalizedQuery))
    : tasks;

  const handleQueryChange = (value: string) => {
    setQuery(value);
    setShowClear(value !== '');
  };

  const clearSearch = () => {
    // Keep the button mounted so focus stays on it after clearing.
    setQuery('');
  };

  return (
    <div className="task-search-region">
      <div className="task-search">
        <input
          type="search"
          className="task-search-input"
          aria-label="Search tasks"
          placeholder="Search tasks"
          value={query}
          onChange={(event) => handleQueryChange(event.target.value)}
        />
        {showClear && (
          <button className="icon-button" type="button" onClick={clearSearch}>
            Clear search
          </button>
        )}
      </div>
      {visibleTasks.length === 0 ? (
        <p className="task-search-empty">No tasks match your search.</p>
      ) : (
        <ul className="task-list">
